const seed = $('Read Seed Sources').item.json;
const raw = $json;
const html = typeof raw === 'string'
  ? raw
  : (typeof raw.data === 'string' ? raw.data : JSON.stringify(raw));

const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const pageTitle = titleMatch ? titleMatch[1].replace(/\s+/g, ' ').trim() : null;

const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 5000);

return {
  json: {
    source_url: seed.source_url,
    page_title: pageTitle,
    fetched_at: new Date().toISOString(),
    extracted_content: text,
    job_id: seed.job_id,
    product_name: seed.product_name,
    issuer_name: seed.issuer_name,
    status: "success"
  }
};
